import{_ as n,o as s,c as i,a5 as e}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"76. Profiling with gprof","description":"The Little Book of C — 76. Profiling with gprof","frontmatter":{"title":"76. Profiling with gprof","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 76. Profiling with gprof","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":76,"sidebarWeight":76,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof.md"};function p(o,a,l,r,c,g){return s(),i("div",null,[...a[0]||(a[0]=[e(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof)</p><p>When your program works but feels slow, guessing isn’t enough, you need to measure. Profiling shows you where your program spends its time, which functions are hot, and where optimization truly matters.</p><p>C gives you a lot of control, but performance tuning without profiling is like driving blindfolded. That’s why we use gprof, the GNU profiler, a tool that measures how long your code spends in each function.</p><h4 id="step-1-what-is-profiling" tabindex="-1">Step 1. What Is Profiling? <a class="header-anchor" href="#step-1-what-is-profiling" aria-label="Permalink to &quot;Step 1. What Is Profiling?&quot;">​</a></h4><p>Profiling is the process of recording runtime statistics such as:</p><ul><li>How many times each function runs.</li><li>How much CPU time each function uses.</li><li>Which functions call which others.</li></ul><p>It helps you find bottlenecks, functions that dominate runtime, and focus your optimization there.</p><h4 id="step-2-enabling-profiling-with-gprof" tabindex="-1">Step 2. Enabling Profiling with gprof <a class="header-anchor" href="#step-2-enabling-profiling-with-gprof" aria-label="Permalink to &quot;Step 2. Enabling Profiling with gprof&quot;">​</a></h4><p>Compile your program with the<code>-pg</code> flag to enable profiling hooks:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -o program</span></span></code></pre></div><p>Run the program normally:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program</span></span></code></pre></div><p>After it finishes, a file named<code>gmon.out</code> is created. This file contains execution data collected during runtime.</p><p>Generate a report:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gprof program gmon.out &gt; analysis.txt</span></span></code></pre></div><p>Now open<code>analysis.txt</code> to see where your program spent its time.</p><h4 id="step-3-example-program" tabindex="-1">Step 3. Example Program <a class="header-anchor" href="#step-3-example-program" aria-label="Permalink to &quot;Step 3. Example Program&quot;">​</a></h4><p>Here’s a small example to demonstrate profiling:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void slow_function(void) {</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 50000000; i++);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void fast_function(void) {</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 5000000; i++);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    slow_function();</span></span>
<span class="line"><span>    fast_function();</span></span>
<span class="line"><span>    slow_function();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -o profile_me</span></span>
<span class="line"><span>./profile_me</span></span>
<span class="line"><span>gprof profile_me gmon.out &gt; report.txt</span></span></code></pre></div><h4 id="step-4-reading-the-gprof-report" tabindex="-1">Step 4. Reading the gprof Report <a class="header-anchor" href="#step-4-reading-the-gprof-report" aria-label="Permalink to &quot;Step 4. Reading the gprof Report&quot;">​</a></h4><p>The report has two key sections:</p><ol><li>Flat Profile</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Flat profile:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Each sample counts as 0.01 seconds.</span></span>
<span class="line"><span>  %   cumulative   self              self     total</span></span>
<span class="line"><span> time   seconds   seconds    calls   ms/call  ms/call  name</span></span>
<span class="line"><span> 66.7      0.20     0.20        2   100.00   100.00  slow_function</span></span>
<span class="line"><span> 33.3      0.30     0.10        1   100.00   100.00  fast_function</span></span></code></pre></div><p>This tells you:</p><ul><li><code>slow_function()</code> took 66% of total time.</li><li><code>fast_function()</code> took 33%.</li></ul><ol start="2"><li>Call Graph</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index % time    self  children    called     name</span></span>
<span class="line"><span>                0.20    0.00       2/2       slow_function</span></span>
<span class="line"><span>                0.10    0.00       1/1       fast_function</span></span></code></pre></div><p>This shows relationships, which functions called which, and how time was distributed among them.</p><h4 id="step-5-profiling-multi-file-programs" tabindex="-1">Step 5. Profiling Multi-File Programs <a class="header-anchor" href="#step-5-profiling-multi-file-programs" aria-label="Permalink to &quot;Step 5. Profiling Multi-File Programs&quot;">​</a></h4><p>When working on multiple<code>.c</code> files, just compile each with<code>-pg</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg -c foo.c</span></span>
<span class="line"><span>gcc -pg -c bar.c</span></span>
<span class="line"><span>gcc -pg foo.o bar.o -o app</span></span></code></pre></div><p>Then run and analyze as before.</p><h4 id="step-6-ignoring-initialization-or-short-runs" tabindex="-1">Step 6. Ignoring Initialization or Short Runs <a class="header-anchor" href="#step-6-ignoring-initialization-or-short-runs" aria-label="Permalink to &quot;Step 6. Ignoring Initialization or Short Runs&quot;">​</a></h4><p>Profiling works best for real workloads. Avoid profiling tiny runs, because initialization costs can dominate and distort results.</p><p>For example, a 10 ms startup delay might look huge if your program only runs 20 ms in total. Use representative input and real loops to get meaningful data.</p><h4 id="step-7-focusing-on-hotspots" tabindex="-1">Step 7. Focusing on Hotspots <a class="header-anchor" href="#step-7-focusing-on-hotspots" aria-label="Permalink to &quot;Step 7. Focusing on Hotspots&quot;">​</a></h4><p>When you know which functions dominate runtime (often the top 5%), you can:</p><ul><li>Inline them manually.</li><li>Use better data structures.</li><li>Reduce allocations.</li><li>Simplify inner loops.</li></ul><p>Optimization is about precision, don’t guess where your code is slow; let the profiler prove it.</p><h4 id="step-8-combining-gprof-with-compiler-optimizations" tabindex="-1">Step 8. Combining gprof with Compiler Optimizations <a class="header-anchor" href="#step-8-combining-gprof-with-compiler-optimizations" aria-label="Permalink to &quot;Step 8. Combining gprof with Compiler Optimizations&quot;">​</a></h4><p>Compare your performance before and after adding optimization flags:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg -O0 main.c -o slow</span></span>
<span class="line"><span>gcc -pg -O3 main.c -o fast</span></span></code></pre></div><p>Then run both and inspect the reports. You’ll see dramatic changes in timing distribution, sometimes even inlined functions disappear entirely from the profile.</p><h4 id="step-9-visualizing-profiles" tabindex="-1">Step 9. Visualizing Profiles <a class="header-anchor" href="#step-9-visualizing-profiles" aria-label="Permalink to &quot;Step 9. Visualizing Profiles&quot;">​</a></h4><p>You can visualize gprof results using gprof2dot and Graphviz:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install gprof2dot</span></span>
<span class="line"><span>gprof program gmon.out | gprof2dot | dot -Tpng -o profile.png</span></span></code></pre></div><p>This generates a call graph image, showing which functions dominate. The thicker the arrow, the more time is spent there.</p><h4 id="step-10-tiny-code-measuring-a-sorting-algorithm" tabindex="-1">Step 10. Tiny Code: Measuring a Sorting Algorithm <a class="header-anchor" href="#step-10-tiny-code-measuring-a-sorting-algorithm" aria-label="Permalink to &quot;Step 10. Tiny Code: Measuring a Sorting Algorithm&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#define N 100000</span></span>
<span class="line"><span>void bubble_sort(int *arr, int n) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n - 1; i++)</span></span>
<span class="line"><span>        for (int j = 0; j &lt; n - i - 1; j++)</span></span>
<span class="line"><span>            if (arr[j] &gt; arr[j + 1]) {</span></span>
<span class="line"><span>                int tmp = arr[j];</span></span>
<span class="line"><span>                arr[j] = arr[j + 1];</span></span>
<span class="line"><span>                arr[j + 1] = tmp;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void fill_random(int *arr, int n) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>        arr[i] = rand() % 100000;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *arr = malloc(N * sizeof(int));</span></span>
<span class="line"><span>    fill_random(arr, N);</span></span>
<span class="line"><span>    bubble_sort(arr, N);</span></span>
<span class="line"><span>    free(arr);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -O0 -o sort_profile</span></span>
<span class="line"><span>./sort_profile</span></span>
<span class="line"><span>gprof sort_profile gmon.out | head -n 20</span></span></code></pre></div><p>Output (excerpt):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  %   cumulative   self              self     total</span></span>
<span class="line"><span> time   seconds   seconds    calls   ms/call  ms/call  name</span></span>
<span class="line"><span> 95.0      0.95     0.95        1   950.00   950.00  bubble_sort</span></span></code></pre></div><p>This tells you 95% of time is spent in<code>bubble_sort()</code>, confirming the algorithmic bottleneck.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Profiling bridges the gap between “feels slow” and knowing why. It helps you:</p><ul><li>Focus optimization effort where it matters most.</li><li>Verify improvements quantitatively.</li><li>Eliminate guesswork.</li></ul><p>In performance engineering, measurement beats intuition every time.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Profile your own sorting or search algorithm.</li><li>Compare results between<code>-O0</code>,<code>-O2</code>, and<code>-O3</code>.</li><li>Profile a multithreaded or I/O-bound program.</li><li>Visualize results with<code>gprof2dot</code>.</li><li>Identify one bottleneck and fix it, then re-profile to see the difference.</li></ol><p>Next, you’ll explore common undefined behaviors in C, the silent bugs that can make your perfectly profiled program crash unpredictably.</p>`,63)])])}const u=n(t,[["render",p]]);export{d as __pageData,u as default};
